import subprocess,pathlib,json,time,hashlib
root=pathlib.Path('/tmp/stanli-data-kernels-evidence')
rows=[]
def run(kind,case,rep,cmd,env=None):
 t=time.time();r=subprocess.run(cmd,capture_output=True,text=True,env=env)
 row=dict(kind=kind,case=case,rep=rep,command=cmd,seconds=time.time()-t,returncode=r.returncode,stdout=r.stdout,stderr=r.stderr)
 rows.append(row);(root/'measurements.json').write_text(json.dumps(rows,indent=2))
 print(kind,case,rep,r.returncode,r.stdout.strip().splitlines()[-1:] ,flush=True)
 if r.returncode:raise RuntimeError(r.stderr)
for rep in range(7):
 for model,n in [('gp_regr',100000),('gp_pois_regr',100000),('eight_schools_noncentered',1000000),('normal_mixture',20000),('arK',20000)]:
  for kind in (['baseline','candidate'] if rep%2==0 else ['candidate','baseline']):
   build='build' if kind=='baseline' else 'build-candidate'
   run(kind,model,rep,[build+'/bench_grad',str(root/f'{model}.sexp'),str(root/f'{model}.json'),str(n)])
for rep in range(3):
 for kind in (['baseline','candidate'] if rep%2==0 else ['candidate','baseline']):
  exe=str(root/'clone-baseline') if kind=='baseline' else 'build-candidate/bench_executor_data'
  run(kind,'synthetic-clones',rep,[exe,'8000000','8'])
  run(kind,'mnist-clones',rep,[str(root/('model-clone-'+kind)),str(root/'nn_rbm1bJ100.sexp'),str(root/'nn_rbm1bJ100.json')])
for rep in range(5):
 for kind in (['baseline','candidate'] if rep%2==0 else ['candidate','baseline']):
  build='build' if kind=='baseline' else 'build-candidate'
  import os
  env=dict(os.environ,STANLI_PROFILE_PREP='1')
  run(kind,'mnist-prep',rep,['/usr/bin/time','-lp',build+'/bench_grad',str(root/'nn_rbm1bJ100.sexp'),str(root/'nn_rbm1bJ100.json'),'--prep'],env)

