#include <stanli/compile.hpp>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <sstream>
#include <memory>
#include <vector>
#include <sys/resource.h>
int main(int argc,char** argv) {
  using namespace stanli;
  if(argc!=3) return 2;
  std::unique_ptr<Executor> proto;
  { std::ifstream f(argv[1]);std::ostringstream text;text<<f.rdbuf();
    auto cm=compile_model(text.str(),DataMap::from_json_file(argv[2]));
    proto=std::make_unique<Executor>(std::move(cm.graph)); cm.bind(*proto); }
  for(int i=0;i<proto->n_params();++i)proto->params_data()[i]=0.01*std::sin(double(i));
  auto t=std::chrono::steady_clock::now();
  std::vector<std::unique_ptr<Executor>> copies;
  for(int i=0;i<7;++i)copies.push_back(std::make_unique<Executor>(*proto));
  double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();
  std::vector<double> ref(proto->n_params()),got(ref.size());double lp=proto->gradient(ref.data());
  for(auto& ex:copies) if(ex->gradient(got.data())!=lp || std::memcmp(ref.data(),got.data(),ref.size()*sizeof(double)))return 1;
  rusage ru;getrusage(RUSAGE_SELF,&ru);
  std::printf("clone_ms=%.6f peak_rss=%ld params=%lld lp=%.17g\n",ms,ru.ru_maxrss,(long long)proto->n_params(),lp);
}
